export const verifiedQuestionCatalogVersion = "0.1.0+57dabd083139"
export const verifiedQuestionCatalog = [{"id":"offline-sync","category":"accounts-sync","question":"Can I use ProgressTracker without internet?","aliases":["What happens when I go offline?","Will my changes sync later?","Can I use this without internet?"],"keywords":["offline","local","sync","internet","device"],"suggestible":true,"sources":["src/db/localRepository.ts","src/services/supabase/syncEngine.ts","src/features/auth/AuthProvider.tsx"],"answer":"Tracker data is stored locally in the browser, so you can continue working while offline. Signed-in account data synchronizes when a connection is available again. Until then, changes on that device may not appear elsewhere."},{"id":"cross-device-sync","category":"accounts-sync","question":"Will my progress appear on another device?","aliases":["How do I sync trackers between devices?","Can I access my data on a new device?"],"keywords":["account","sign in","sync","devices","cloud"],"suggestible":true,"sources":["src/features/auth/AuthProvider.tsx","src/services/supabase/syncEngine.ts"],"answer":"Cross-device synchronization is available when you sign in to the same account and the devices are online. Guest data is stored locally on the device and does not automatically appear on another device."},{"id":"sync-conflicts","category":"accounts-sync","question":"What happens if two devices edit the same day?","aliases":["How does sync handle conflicting edits?","Will ProgressTracker merge two versions automatically?"],"keywords":["conflict","revision","sync","devices","edit"],"suggestible":true,"sources":["src/services/supabase/syncEngine.ts","src/db/syncConflictRepository.ts","src/db/syncConflictRepository.test.ts"],"answer":"When edits cannot be reconciled safely, sync records a conflict for you to resolve instead of silently combining incompatible versions. Review the conflict in the app’s sync/conflict flow; do not assume both edits were merged."},{"id":"account-signin","category":"accounts-sync","question":"How do I sign in or create an account?","aliases":["Can I sign in with an email link?","How do I register?"],"keywords":["sign in","create account","email link","password","authentication"],"suggestible":true,"sources":["src/features/auth/AuthPage.tsx","src/features/auth/authService.ts","src/features/auth/AuthPage.test.tsx"],"answer":"Use the account screen to request an email sign-in link or choose password sign-in. Choose Create account when registering a new account; using an email sign-in link for the first time creates an account for that email."},{"id":"workspace-backup","category":"accounts-sync","question":"Can I back up or restore my workspace data?","aliases":["How do I export my progress?","Can I import a workspace backup?"],"keywords":["backup","export","restore","JSON","workspace","sync conflicts"],"suggestible":true,"sources":["src/features/auth/WorkspaceBackup.tsx","src/db/workspaceBackup.ts","src/db/workspaceBackup.test.ts"],"answer":"Settings provides a local workspace backup you can download as JSON and restore into the same guest workspace or account. Restore previews changes, adds missing records, skips identical records, and stops if it finds a conflicting ID or date. Keep the backup file private."},{"id":"signout-local-data","category":"accounts-sync","question":"What happens to local workspace data when I sign out?","aliases":["Does signing out erase check-ins from this device?","Will my local progress remain after sign-out?"],"keywords":["sign out","local workspace","check-ins","data","account"],"suggestible":true,"sources":["src/features/auth/AuthProvider.tsx","src/db/localRepository.ts"],"answer":"Signing out ends the account session; it does not itself delete the local workspace records. Account data remains associated with its local workspace, and the app uses a workspace-selection step when choosing guest data after sign-out."},{"id":"offline-sync-later","category":"accounts-sync","question":"What happens to a check-in I save while offline?","aliases":["Will my offline entry upload when I reconnect?","Does a disconnected check-in stay on this device?"],"keywords":["offline check-in","pending sync","reconnect","local storage"],"suggestible":true,"sources":["src/db/localRepository.ts","src/services/supabase/syncEngine.ts","src/features/auth/AuthProvider.tsx"],"answer":"The check-in is saved locally and its account-sync work remains pending until a connection is available. It may not appear on another device before synchronization completes."},{"id":"sync-deletion","category":"accounts-sync","question":"Does clearing a check-in sync to my other devices?","aliases":["Will a cleared entry disappear from my other device?","Does a check-in deletion upload when I reconnect?"],"keywords":["clear check-in","sync","other devices","deletion marker"],"suggestible":true,"sources":["src/db/localRepository.ts","src/services/supabase/syncEngine.ts"],"answer":"For a signed-in account, clearing queues a deletion update for synchronization. Other devices reflect the change after they synchronize with the account; while offline, they may still show their earlier local copy."},{"id":"sync-conflict-preserves-versions","category":"accounts-sync","question":"What information is kept when two device edits conflict?","aliases":["Does sync keep both versions of a conflict?","Can ProgressTracker merge conflicting tracker changes automatically?"],"keywords":["sync conflict","local version","remote version","revision","resolution"],"suggestible":true,"sources":["src/services/supabase/syncEngine.ts","src/db/syncConflictRepository.ts","src/db/syncConflictRepository.test.ts"],"answer":"When a revision conflict cannot be reconciled safely, the sync flow records the conflicting local and remote data for you to resolve. It does not silently blend incompatible changes. Review the conflict before choosing which version to keep."},{"id":"sync-preference-scope","category":"accounts-sync","question":"Do workspace time zone and appearance settings sync between devices?","aliases":["Will my theme and calendar time zone follow me to another device?","Are workspace display preferences stored in my account?"],"keywords":["settings","time zone","appearance","sync","devices"],"suggestible":true,"sources":["src/features/settings/WorkspaceTimeZone.tsx","src/features/settings/appearance.ts","src/features/settings/UnifiedSettings.test.tsx"],"answer":"No. The workspace time zone and appearance preferences are stored locally and currently do not synchronize between devices. Set them separately in each workspace."},{"id":"ai-help-private-data","category":"ai-help","question":"Can AI Help see my tracker entries?","aliases":["Does Groq receive my personal progress?","What data is sent when I ask a question?","Can AI Help read my check-in values?"],"keywords":["privacy","tracker entries","personal data","Groq","AI Help"],"suggestible":true,"sources":["src/features/ai-help/aiHelpService.ts","supabase/functions/ai-help/index.ts","supabase/functions/ai-help/assistantCore.ts"],"answer":"AI Help answers questions about how the product works; its request includes your question and limited conversation context, not your tracker entries. Do not include private tracker details in a question or support message."},{"id":"ai-help-suggested-offline","category":"ai-help","question":"Can I use suggested AI Help questions while offline?","aliases":["Do the suggested questions work without internet?","Can AI Help show a saved answer if I am disconnected?"],"keywords":["AI Help","suggestions","offline","verified answer","internet"],"suggestible":true,"sources":["src/features/ai-help/aiHelpService.ts","src/features/ai-help/AIHelpAssistant.tsx"],"answer":"Yes, a displayed verified suggestion opens its bundled answer without a network request. Manually typed questions need a connection for the full retrieval service; only questions matched by the smaller local help catalog can receive a local answer offline."},{"id":"ai-help-typed-retrieval","category":"ai-help","question":"How does AI Help handle a question I type myself?","aliases":["Does free-form Ask ProgressTracker use the verified answers?","What happens when I ask a question that is not a suggestion?"],"keywords":["AI Help","typed question","free-form","knowledge retrieval","source evidence"],"suggestible":true,"sources":["src/features/ai-help/aiHelpService.ts","supabase/functions/ai-help/index.ts","supabase/functions/ai-help/assistantCore.ts"],"answer":"When online, a typed question is checked against verified Q&A first. If no clear catalog answer applies, the service can use relevant product documentation and reviewed source evidence to form a grounded answer. AI Help does not receive your tracker entries."},{"id":"calendar-content","category":"calendar","question":"What does the calendar show?","aliases":["What do the calendar colors mean?","Can I see progress by date?"],"keywords":["calendar","activity","status","heatmap","date"],"suggestible":true,"sources":["src/features/calendar/CalendarPage.tsx","src/domain/trackers/activityHeatmap.ts"],"answer":"The calendar lets you navigate dates and review tracker activity for the selected period. Its date indicators summarize scheduled opportunities and saved progress; open a date to review or update the entries available for that day."},{"id":"calendar-activity-statuses","category":"calendar","question":"What do the Calendar activity statuses mean?","aliases":["What is the difference between pending, missed, and no progress?","What do the status labels in Calendar mean?"],"keywords":["Calendar","status","pending","missed","completed","historical"],"suggestible":true,"sources":["src/domain/trackers/activityStatus.ts","src/features/calendar/CalendarPage.tsx"],"answer":"Completed means a saved recorded check-in met the configured success rule. Partial means it has positive progress but misses that rule; No progress means a saved recorded check-in has no qualifying positive progress. Missed is derived when a required past date has no active saved entry, while Skipped is an intentional saved outcome. Pending is for an open opportunity today; Upcoming is a future opportunity. Rest day is an in-period date excluded by the schedule in Standard Mode. Outside period has no current opportunity; a saved entry there is shown as a Historical entry. Holiday is a workspace-wide date. Expand the Status guide to see all statuses, including context states. In All Trackers, a date summarizes active trackers; mixed statuses are marked on the cell and selecting the date shows each tracker’s result. The summary and saved-entry count use that same tracker scope. Selecting one tracker, including a paused or archived tracker, shows its retained activity."},{"id":"calendar-inspect-past-date","category":"calendar","question":"How do I inspect tracker activity on a past date?","aliases":["Can I open a previous day in Calendar?","Where can I see what happened on a particular date?"],"keywords":["Calendar","past date","select date","activity"],"suggestible":true,"sources":["src/features/calendar/CalendarPage.tsx","src/features/calendar/CalendarPage.test.tsx"],"answer":"Open Calendar, navigate to the month, and select the date. The selected-day panel shows statuses and saved values by tracker; use its History link to review an entry or its check-in action when available."},{"id":"calendar-rest-day","category":"calendar","question":"How do rest days appear in Calendar?","aliases":["Does Calendar show unscheduled tracker days?","What status does an off day have?"],"keywords":["Calendar","rest day","unscheduled","tracker schedule"],"suggestible":true,"sources":["src/domain/trackers/activityStatus.ts","src/features/calendar/CalendarPage.tsx"],"answer":"In Standard Mode, an in-period date excluded by the active tracker’s schedule is a Rest day. Strict Mode makes every in-period date an opportunity, including schedule rest days. Dates before the effective start or after the deadline are Outside period, not Rest days. Saved check-ins remain visible on rest days and outside the active period."},{"id":"calendar-zero-activity","category":"calendar","question":"Does a recorded zero count as activity in Calendar?","aliases":["Is zero different from no check-in on the calendar?","Why is my zero entry not marked completed?"],"keywords":["Calendar","zero","quantity","recorded","success rule"],"suggestible":true,"sources":["src/domain/trackers/activityStatus.ts","src/domain/trackers/progression.ts"],"answer":"A saved zero is a recorded value, so it is different from an empty date. Whether the day is Completed depends on the tracker’s success rule; zero may be recorded without qualifying, and the Calendar can show No progress."},{"id":"calendar-holiday-entry","category":"calendar","question":"Does a saved check-in stay visible on a holiday?","aliases":["Does marking a holiday hide progress already recorded?","Can a holiday date still show my check-in?"],"keywords":["Calendar","holiday","saved check-in","retain","workspace"],"suggestible":true,"sources":["src/domain/trackers/activityStatus.ts","src/features/calendar/CalendarPage.tsx"],"answer":"Yes. The selected-day details and History retain saved check-ins. Standard Mode’s holiday marker can appear alongside the saved outcome; Strict Mode still requires activity, so a missing past check-in can be Missed on a holiday."},{"id":"heatmap-normalized","category":"calendar","question":"What does the Insights heatmap measure?","aliases":["How are the heatmap colors calculated?","Does one heatmap shade mean one check-in?"],"keywords":["heatmap","eligible opportunities","qualifying check-ins","percent","Insights"],"suggestible":true,"sources":["src/domain/trackers/activityHeatmap.ts","src/features/dashboard/DashboardPage.tsx"],"answer":"For each date, the heatmap compares qualifying check-ins with eligible opportunities and colors the result by that day’s percentage. In an all-tracker view, it combines opportunity counts across active trackers while applying each tracker’s Standard or Strict Mode rules."},{"id":"calendar-versus-history","category":"calendar","question":"Why does Calendar show dates that I do not see in History?","aliases":["What is the difference between Calendar and History?","Why is an empty date on Calendar missing from my History list?"],"keywords":["Calendar","History","activity status","saved check-ins","missing"],"suggestible":true,"sources":["src/features/calendar/CalendarPage.tsx","src/features/history/HistoryPage.tsx"],"answer":"Calendar summarizes tracker status across selected dates, including pending, missed, holiday, and rest days. History lists saved check-ins and holidays in its selected range, with a separate recent missing-opportunity review; an empty calendar date is not necessarily a saved history entry."},{"id":"skipped-vs-unchecked","category":"check-ins","question":"What is the difference between a skipped and unchecked day?","aliases":["Is skipping the same as leaving a day blank?","What does an unchecked date mean?","What is the difference between skipped and not checked?"],"keywords":["skipped","unchecked","absent","missing check-in","outcome"],"suggestible":true,"sources":["src/domain/trackers/missingCheckIns.ts","src/domain/trackers/types.ts","src/features/history/HistoryPage.tsx"],"answer":"A skipped day is an explicitly saved check-in marked as skipped. An unchecked past date has no saved entry and is shown as Missed only if it was a required opportunity. A saved recorded check-in that fails its success rule remains distinct: it appears as Partial when it has positive progress, or No progress when it does not. Missed is derived and is never saved automatically."},{"id":"edit-past-checkin","category":"check-ins","question":"Can I edit a past check-in?","aliases":["Can I change yesterday’s progress?","How do I correct an old entry?"],"keywords":["history","edit","past date","check-in","values"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/progression.ts"],"answer":"Yes. Open History, select the saved date and tracker entry, then edit its values. The latest saved revision for that date is used in current calculations."},{"id":"clear-checkin","category":"check-ins","question":"What happens if I clear a check-in?","aliases":["Can I undo a check-in?","What happens if I clear yesterday’s progress?"],"keywords":["clear","delete","history","missing","re-record","check-in"],"suggestible":true,"sources":["src/features/shared/ClearCheckInAction.tsx","src/db/localRepository.ts","src/domain/trackers/missingCheckIns.ts"],"answer":"Clearing removes the saved check-in from current progress calculations. If that date was a past opportunity, it can then appear in missing check-in review. You can record the date again by creating a new check-in."},{"id":"numeric-zero-vs-empty","category":"check-ins","question":"Is entering zero different from leaving a number blank?","aliases":["Does zero count as no progress?","Is a blank quantity treated as zero?"],"keywords":["quantity","zero","blank","observation","numeric"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/features/shared/TrackerEntryFields.tsx","src/domain/trackers/schema.ts"],"answer":"Yes. Zero is a recorded numeric value and can be included in observations. A blank field is not a numeric observation. Whether a recorded zero qualifies as a successful check-in depends on the tracker’s success rules."},{"id":"mark-missed","category":"check-ins","question":"What happens when I mark a check-in as skipped?","aliases":["Is marking a day missed different from leaving it blank?","Does Mark as skipped break my streak?"],"keywords":["mark as skipped","skipped","outcome","unchecked","streak"],"suggestible":true,"sources":["src/domain/trackers/types.ts","src/domain/trackers/progression.ts","src/features/today/TodayPage.tsx"],"answer":"Mark as skipped saves an intentional skipped outcome for that date. It is not the same as a derived Missed date or a saved No progress result. On a required opportunity, it does not qualify for a streak. Leaving a date unchecked creates no saved entry; after a required date elapses, it can appear as Missed."},{"id":"custom-checkin-fields","category":"check-ins","question":"What are custom check-in fields?","aliases":["Can I add a note to a check-in?","Do notes count toward goal progress?"],"keywords":["notes","custom fields","context","measure","goal progress"],"suggestible":true,"sources":["src/features/trackers/TrackerConfigurationEditor.tsx","src/features/shared/TrackerEntryFields.tsx","src/domain/trackers/types.ts","src/features/shared/TrackerEntryFields.test.tsx"],"answer":"Custom check-in fields add context to an entry, such as a note or selected answer. They are separate from tracker measures and are not used as numeric goal totals."},{"id":"checkin-types","category":"check-ins","question":"What kinds of values can I record in a tracker?","aliases":["Can I track a number or a yes/no habit?","What measure types are available?"],"keywords":["Yes/No","quantity","measures","recorded values","legacy"],"suggestible":true,"sources":["src/domain/trackers/types.ts","src/features/trackers/trackerSetupSchema.ts","src/features/shared/TrackerEntryFields.tsx"],"answer":"New tracker measures use Yes/No or Quantity values. Existing trackers may also contain legacy measure types such as Duration or Checklist, which remain supported for their saved history."},{"id":"checkin-empty-versus-zero-status","category":"check-ins","question":"Why can a saved zero show no progress instead of a missed day?","aliases":["Is a zero entry treated as unchecked?","How does Calendar distinguish zero from no check-in?"],"keywords":["zero","no progress","missed","saved entry","activity status"],"suggestible":true,"sources":["src/domain/trackers/activityStatus.ts","src/features/calendar/CalendarPage.tsx"],"answer":"A saved zero is still a check-in, not a missed day. Calendar evaluates it against the tracker’s success rule and may show No progress; if the rule explicitly accepts zero, it can show Completed. Missed means an elapsed required opportunity has no active saved check-in. An open opportunity today is Pending, and a future opportunity is Upcoming."},{"id":"checkin-resave-same-date","category":"check-ins","question":"What happens if I save a check-in again for the same date?","aliases":["Can a tracker have two check-ins on one day?","Does saving another entry replace my check-in for that date?"],"keywords":["same date","edit","save","latest revision","check-in"],"suggestible":true,"sources":["src/db/localRepository.ts","src/domain/trackers/planning.ts"],"answer":"The app keeps one active check-in per tracker and date. Saving again updates that date’s entry, and calculations use the latest live revision rather than adding a second daily record."},{"id":"checkin-note-vs-measure","category":"check-ins","question":"Does a check-in note count as a measure value?","aliases":["Can a note contribute to my numeric goal?","Are custom answers included in tracker statistics?"],"keywords":["note","custom field","measure","metric","goal progress"],"suggestible":true,"sources":["src/features/trackers/TrackerConfigurationEditor.tsx","src/features/shared/TrackerEntryFields.tsx","src/domain/trackers/analytics.ts"],"answer":"No. A note or custom check-in answer adds context to the entry. Goal calculations and measure statistics use tracker measure values, not those custom fields."},{"id":"guest-mode","category":"getting-started","question":"Can I use ProgressTracker as a guest?","aliases":["Do I need an account to start tracking?","What happens to guest data?"],"keywords":["guest","account","local storage","sign in","tracker"],"suggestible":true,"sources":["src/features/auth/AuthProvider.tsx","src/db/localRepository.ts","src/features/auth/AuthPage.tsx","src/features/auth/AuthProvider.test.tsx"],"answer":"You can use ProgressTracker without signing in. Guest tracker data is stored locally in the browser on that device. Signing in enables account synchronization, but guest data does not automatically appear on another device."},{"id":"create-tracker","category":"getting-started","question":"How do I create a tracker?","aliases":["How do I start tracking a habit?","Where do I add a new tracker?"],"keywords":["create","setup","habit","goal","schedule","measure"],"suggestible":true,"sources":["src/features/trackers/TrackerSetupPage.tsx","src/features/trackers/TrackerSetupPage.test.tsx","src/features/trackers/trackerSetupSchema.ts"],"answer":"Open Trackers and choose Create tracker. Give it a name, choose the tracker kind and measures, then set its schedule and active dates. Save the form to begin using it. New measures support Yes/No or Quantity; some existing trackers can retain legacy measure types."},{"id":"daily-vs-cumulative-goal","category":"goals","question":"What is the difference between daily and cumulative goals?","aliases":["How does cumulative progress work?","Does my goal target reset every day?"],"keywords":["daily plan","cumulative plan","target","allocations","progress"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/allocationPreview.ts","src/domain/trackers/goalPlanning.test.ts","src/features/goals/GoalsPage.tsx"],"answer":"A daily plan sets a target for each planned day. A cumulative plan sets a total amount to reach across its date range, with progress allocated across the plan. Which model applies depends on the saved goal plan."},{"id":"milestones","category":"goals","question":"How are milestones calculated?","aliases":["When is a milestone reached?","What does a linked milestone mean?"],"keywords":["goal","milestone","target","progress","linked measure"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/allocationPreview.ts","src/features/goals/GoalsPage.tsx"],"answer":"A milestone is reached when the progress used by its linked goal plan meets the milestone target. The exact progress comes from that goal’s daily or cumulative plan and its eligible recorded values."},{"id":"goal-deadline","category":"goals","question":"Can a goal have a deadline?","aliases":["How does a goal deadline work?","What happens when a goal’s end date passes?"],"keywords":["goal","deadline","cumulative","active period","target"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/features/trackers/GoalPlanningEditor.tsx","src/domain/trackers/goalPlanning.test.ts"],"answer":"Yes. A goal can use a deadline to bound its planned date range, especially for cumulative targets. Progress and pacing are calculated within that plan period; dates after the tracker deadline are not included in its cumulative progress."},{"id":"complete-goal","category":"goals","question":"When is a goal complete?","aliases":["How do I know I reached my goal target?","Does reaching a milestone complete the goal?"],"keywords":["goal","completed","target","progress","milestone"],"suggestible":true,"sources":["src/features/goals/GoalsPage.tsx","src/domain/trackers/planning.ts","src/domain/trackers/goalPlanning.test.ts"],"answer":"The goal plan reports its target as complete when no planned work remains. The Goals page also shows the tracker’s saved status, so the displayed status can depend on both the goal state and plan. A milestone is a checkpoint within a plan; reaching one does not by itself mean the overall target is complete."},{"id":"goal-daily-missing","category":"goals","question":"How does a daily goal plan treat a missing date?","aliases":["Does a missed day count as meeting my daily target?","What happens to a daily target when I do not check in?"],"keywords":["daily goal","missing","missed","target","schedule"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/goalPlanning.test.ts"],"answer":"A past scheduled date without a usable check-in is treated as missed in the daily plan. Today remains pending while it is still open, and rest days, holidays, and future dates are shown separately rather than as missed opportunities."},{"id":"goal-cumulative-snapshot","category":"goals","question":"Do snapshot check-ins add together toward a cumulative goal?","aliases":["Are repeated snapshot values summed for a total goal?","Which entries count toward cumulative progress?"],"keywords":["cumulative goal","snapshot","incremental","total progress"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/features/trackers/GoalPlanningEditor.tsx","src/domain/trackers/goalPlanning.test.ts"],"answer":"No. Cumulative progress sums entries configured as incremental. Snapshot values describe a level at a point in time and are not added together across dates."},{"id":"goal-clearing-entry","category":"goals","question":"Does clearing a check-in change goal progress?","aliases":["Will a deleted entry reduce my goal total?","Does removing a historical check-in recalculate the goal?","Can clearing a check-in change my goal progress?","Will my goal total go down if I clear an entry?","Does removing a check-in update the Goals page?"],"keywords":["goal progress","clear check-in","delete entry","recalculate"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/db/localRepository.ts","src/features/history/HistoryPage.tsx"],"answer":"Goal progress is calculated from active saved entries, so clearing a check-in can change the displayed progress or pacing. The effect depends on the plan and whether that entry contributes a qualifying value."},{"id":"goal-target-change","category":"goals","question":"What happens if I change a goal target?","aliases":["Does editing my target change saved check-ins?","Will a new goal target recalculate my plan?"],"keywords":["goal target","edit plan","recalculation","saved progress"],"suggestible":true,"sources":["src/features/goals/GoalsPage.tsx","src/features/trackers/GoalPlanningEditor.tsx","src/domain/trackers/planning.ts"],"answer":"The plan and its remaining pace are recalculated against the new target and existing saved progress. Changing the target does not rewrite the check-ins themselves."},{"id":"goal-metric-unit","category":"goals","question":"Where does a goal’s unit come from?","aliases":["How does a goal know whether progress is pages or minutes?","Can I choose a different unit for goal progress?"],"keywords":["goal","measure","unit","metric","quantity"],"suggestible":true,"sources":["src/features/goals/GoalsPage.tsx","src/domain/trackers/planning.ts","src/features/trackers/GoalPlanningEditor.tsx"],"answer":"The goal uses the unit of its linked tracker measure. Choose or edit the measure’s unit in tracker configuration; the goal plan displays values in that unit rather than converting them."},{"id":"history-includes","category":"history","question":"What does History include?","aliases":["What can I see in History?","Why does History not show every date?","Where can I review saved check-ins?"],"keywords":["saved entries","historical","holidays","missing check-ins","date","values"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/missingCheckIns.ts","src/features/history/HistoryPage.test.tsx"],"answer":"History shows saved check-ins and their recorded values for past dates, along with workspace holidays in the selected date range. It also offers a missing check-in review for unresolved opportunities in the previous seven completed days. Dates that were not tracking opportunities are not shown as missing, and today is not treated as overdue."},{"id":"history-clear-note","category":"history","question":"Does clearing a check-in remove its note?","aliases":["Does clearing remove a check-in note?","What happens to a note when I clear its check-in?","Is the note kept if I delete an old entry?"],"keywords":["clear check-in","note","history","deleted entry"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/db/localRepository.ts"],"answer":"The note belongs to the saved check-in, so clearing the check-in removes it from active History along with the entry. Clearing does not provide a separate option to keep the note while removing the check-in."},{"id":"history-clear-sync","category":"history","question":"Is clearing a check-in the same as permanently erasing it everywhere?","aliases":["Does clearing permanently delete a check-in from storage?","Is a cleared entry removed from the cloud too?"],"keywords":["clear","permanent deletion","tombstone","sync","history"],"suggestible":false,"sources":["src/db/localRepository.ts","src/services/supabase/syncEngine.ts","src/features/history/HistoryPage.tsx"],"answer":"Clearing removes the entry from active history on this device and queues a deletion update for account sync when available. The app uses deletion state during synchronization; clearing should not be treated as proof that every stored copy or backup has been permanently erased."},{"id":"history-reenter-cleared","category":"history","question":"Are my old values restored when I check in again after clearing?","aliases":["Can I undo a cleared check-in by logging again?","What if I want to add progress on that date after clearing it?"],"keywords":["clear","re-enter","save","check-in","date"],"suggestible":true,"sources":["src/db/localRepository.ts","src/features/history/HistoryPage.tsx"],"answer":"No. Clearing removes the entry from active history, so its old values are not filled back into a new check-in. You can save progress for that tracker and date again by entering the values you want to record."},{"id":"history-cleared-missing","category":"history","question":"Why can a cleared date appear as a missing check-in?","aliases":["Does clearing make an old scheduled day missing?","Why did History list a date after I removed its entry?"],"keywords":["clear","missing check-in","scheduled opportunity","history"],"suggestible":true,"sources":["src/domain/trackers/missingCheckIns.ts","src/features/history/HistoryPage.tsx"],"answer":"The missing-check-in review looks for past opportunities without an active saved entry. After you clear an entry, a past date can qualify as missing if it is still an active opportunity under that tracker’s schedule, mode, and holiday rules."},{"id":"history-clear-streak","category":"history","question":"Does clearing a check-in affect my streak?","aliases":["Will deleting a past entry recalculate my streak?","What happens to a streak after I clear one day?"],"keywords":["clear check-in","streak","recalculation","opportunity"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/progression.ts"],"answer":"Yes, streaks are calculated from active saved entries, so clearing one can change the current or longest streak. The result depends on whether that date is a counted opportunity under Standard or Strict Mode and the tracker’s schedule and holiday rules."},{"id":"history-outside-period","category":"history","question":"Why does History label an entry as outside the tracker period?","aliases":["What does Historical mean next to an old check-in?","Why is my saved entry not counted in current progress?"],"keywords":["History","historical entry","start date","deadline","active period"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/activityStatus.ts","src/domain/trackers/planning.ts"],"answer":"The entry was saved on a date outside the tracker’s current active period, which is bounded by its effective start date and deadline. History keeps the entry visible, but it does not count toward current period calculations."},{"id":"history-seven-day-review","category":"history","question":"How far back does History review missing check-ins?","aliases":["Can History find older missed dates?","Does the missing section cover the whole tracker history?"],"keywords":["History","missing check-ins","seven days","review window"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/missingCheckIns.ts"],"answer":"The missing check-in section reviews unresolved opportunities in the previous seven completed days. It is a short review window, not a list of every gap in the tracker’s history; use Calendar to inspect older dates."},{"id":"history-cleared-holiday","category":"history","question":"Can a cleared check-in on a holiday become a missing date?","aliases":["Will clearing a holiday entry create a missed check-in?","Does the missing review include holidays after I clear them?"],"keywords":["cleared check-in","holiday","missing","Strict Mode","Standard Mode"],"suggestible":true,"sources":["src/domain/trackers/missingCheckIns.ts","src/domain/trackers/planning.ts","src/domain/trackers/missingCheckIns.test.ts"],"answer":"In Standard Mode, holidays are excluded from scheduled opportunities, so a cleared holiday entry is not listed as missing. Strict Mode treats every active date, including holidays, as an opportunity; a past cleared holiday can therefore appear in the missing review."},{"id":"missing-checkins","category":"history","question":"Where can I find missing check-ins?","aliases":["How do I review missed days?","Can I find dates I forgot to log?","Where do I review missed check-ins?"],"keywords":["missing","overdue","history","schedule","past opportunity"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/missingCheckIns.ts"],"answer":"Open History and review its missing check-in section. It lists past unresolved opportunities for active trackers, based on each tracker’s active dates, schedule, Strict Mode, and workspace holidays. It does not list today as missing."},{"id":"create-holiday","category":"holidays","question":"How do I add a holiday?","aliases":["Can I mark a day as a break?","How do I add a retroactive holiday?"],"keywords":["holiday","break","date","reason","workspace"],"suggestible":true,"sources":["src/features/holidays/HolidaysPage.tsx","src/domain/holidays.ts","src/domain/holidays.test.ts"],"answer":"Open Holidays & breaks, choose a date, and save the holiday. You can add a reason and choose a past date; holidays apply across the workspace rather than to only one tracker."},{"id":"delete-holiday","category":"holidays","question":"What happens if I delete a holiday?","aliases":["Does removing a holiday change saved check-ins?","Can I undo a workspace break?"],"keywords":["holiday","delete","saved check-in","schedule","history"],"suggestible":true,"sources":["src/features/holidays/HolidaysPage.tsx","src/domain/holidays.ts"],"answer":"Deleting a holiday removes that date’s break from future calculations. Any check-ins already saved for the date remain saved; changing the holiday does not erase them."},{"id":"holidays-streaks","category":"holidays","question":"Do holidays count against my streak?","aliases":["How do holidays affect scheduled check-ins?","Does a holiday pause my tracker?","Do holidays count against my streak?"],"keywords":["holiday","streak","scheduled","strict mode","recorded entry"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/holidays.ts"],"answer":"In Standard Mode, a holiday removes that date from scheduled streak opportunities. In Strict Mode, dates remain daily opportunities, so a holiday by itself does not excuse a missed day. A saved check-in remains visible in either mode; a qualifying one counts in Strict Mode. Goal plans use their own schedule rules."},{"id":"holiday-all-trackers","category":"holidays","question":"Do workspace holidays apply to every tracker?","aliases":["Can I make a holiday for just one tracker?","Is a holiday shared across my trackers?"],"keywords":["workspace holiday","all trackers","schedule","break"],"suggestible":true,"sources":["src/domain/holidays.ts","src/features/holidays/HolidaysPage.tsx"],"answer":"Yes. Holidays are workspace-wide dates, not tracker-specific settings. Tracker opportunity behavior depends on mode: Standard Mode pauses scheduled opportunities, while Strict Mode counts every active date. Goal plans account for holidays according to their own planning rules."},{"id":"holiday-remove-recalculates","category":"holidays","question":"What changes when I remove a holiday?","aliases":["Does deleting a holiday make that date count again?","Will removing a holiday change my streak or statistics?"],"keywords":["holiday","remove","schedule","recalculate","streak"],"suggestible":true,"sources":["src/domain/holidays.ts","src/domain/trackers/progression.ts","src/domain/trackers/analytics.ts"],"answer":"Removing the holiday makes the date subject to the tracker’s usual mode and schedule rules again. Calculated streaks and statistics can therefore change, but saved check-ins are not removed."},{"id":"holiday-log-progress","category":"holidays","question":"Can I record progress on a holiday?","aliases":["Are check-ins allowed during a workspace break?","Can I voluntarily log on a holiday?"],"keywords":["holiday","voluntary check-in","saved entry","calendar"],"suggestible":true,"sources":["src/features/calendar/CalendarPage.tsx","src/features/today/TodayPage.tsx","src/domain/trackers/progression.ts"],"answer":"Yes. A holiday does not prevent a check-in from being saved. Calendar offers a voluntary check-in on an active tracker’s holiday, and the saved entry remains visible. In Standard Mode, the entry is saved and included in applicable metrics, but the holiday does not add a scheduled streak opportunity. In Strict Mode, the holiday remains a required opportunity, and the entry counts toward the streak only if it meets the tracker’s streak qualification."},{"id":"holiday-standard-v-strict","category":"holidays","question":"Why can a holiday be missed in Strict Mode?","aliases":["Why does Strict Mode still expect a check-in on a holiday?","Does Strict Mode pause for workspace holidays?"],"keywords":["Strict Mode","holiday","opportunity","missed","streak"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/trackers/progression.test.ts"],"answer":"Strict Mode treats every date in the tracker’s active period as an opportunity, including holidays. Without a qualifying check-in, an elapsed holiday can break the streak. Standard Mode excludes holidays from scheduled opportunities."},{"id":"insight-tracker-cards","category":"insights","question":"What does the Your Trackers section show?","aliases":["What are the tracker cards in Insights?","What information appears on an Insights tracker card?"],"keywords":["Insights","tracker cards","current date","status","streak","latest check-in"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/features/dashboard/DashboardPage.test.tsx"],"answer":"Each active tracker card is a snapshot for the workspace-local current date. It shows today’s status, that tracker’s current streak and personal best, and its latest saved check-in with that entry’s date, outcome, and values. These refer to separate dates and purposes."},{"id":"insight-current-status","category":"insights","question":"Does an Insights tracker card show today or my latest check-in?","aliases":["What date does a tracker card represent?","Is the status on my tracker card from today or my last entry?"],"keywords":["Insights","snapshot date","current status","latest saved entry"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/features/dashboard/DashboardPage.test.tsx"],"answer":"The card’s status and streak are a snapshot as of today in your workspace time zone. The separate “Latest check-in” area shows the newest saved entry and its actual date, which may be earlier."},{"id":"insight-latest-checkin","category":"insights","question":"What does the latest check-in date on an Insights card mean?","aliases":["Does latest check-in mean I logged today?","Why is the check-in date on my card from an earlier day?"],"keywords":["latest check-in","saved entry","date","Insights"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/db/localRepository.ts"],"answer":"It is the date of the most recent active saved check-in for that tracker. It does not imply that you checked in today. Cleared entries are excluded; if no active entry exists, the card says “No check-ins yet.”"},{"id":"insight-empty-tracker","category":"insights","question":"Why does an Insights card say no check-ins yet?","aliases":["What does “No check-ins yet” mean on my tracker?","Why is there no latest entry on a tracker card?"],"keywords":["Insights","empty tracker","no check-ins","latest entry"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/features/dashboard/DashboardPage.test.tsx"],"answer":"There is no active saved check-in for that tracker. Today’s status is shown separately, so a holiday or rest day does not mean an unfinished check-in; it describes today’s tracking status."},{"id":"insight-streak-personal-best","category":"insights","question":"What do current streak and personal best mean on an Insights card?","aliases":["What is the personal best on my tracker card?","How are the two streak numbers on Insights different?"],"keywords":["current streak","personal best","longest streak","Insights"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/domain/trackers/progression.ts","src/domain/trackers/progression.test.ts"],"answer":"Current streak is the qualifying run through today under the tracker’s mode. Personal best is the longest qualifying run in its saved history. Standard Mode lets holidays and rest days preserve continuity without adding to the count; Strict Mode requires a qualifying entry on every active calendar date, including holidays and rest days."},{"id":"insight-holiday-status","category":"insights","question":"Why does today’s card status differ from my latest check-in?","aliases":["Why does Insights show a holiday when my last entry was completed?","Can the latest check-in and today’s status be different?"],"keywords":["Insights","today","holiday","latest check-in","current status"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/domain/trackers/activityStatus.ts","src/features/dashboard/DashboardPage.test.tsx"],"answer":"Today’s status and the latest saved check-in describe different dates. A holiday can be today’s workspace status while the latest check-in remains an earlier entry; the card labels that entry with its own date and outcome."},{"id":"insight-timezone-date","category":"insights","question":"Which time zone determines the date shown in Insights?","aliases":["Is the Insights snapshot date local to my workspace?","Why does the Insights date change around midnight?"],"keywords":["Insights","workspace time zone","snapshot date","midnight"],"suggestible":true,"sources":["src/features/dashboard/DashboardPage.tsx","src/db/calendarDate.ts","src/features/settings/WorkspaceTimeZone.tsx"],"answer":"Insights uses the current date in the workspace’s selected time zone. Because that date can differ from UTC or your device’s other time zone, the snapshot may change at a different midnight."},{"id":"reminder-limits","category":"notifications","question":"Do reminders arrive when the app is closed?","aliases":["Are reminders sent in the background?","Why did I not get a push notification?"],"keywords":["notification","reminder","foreground","background","push"],"suggestible":true,"sources":["src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/capabilities.ts"],"answer":"The current reminder monitor works while the app is open in the foreground. Background delivery depends on separate push delivery setup, so browser permission alone does not guarantee a reminder when the app is closed."},{"id":"notification-preferences","category":"notifications","question":"Where can I change notification preferences?","aliases":["How do I turn reminders on or off?","Can I change reminder settings?"],"keywords":["reminders","notifications","settings","browser permission"],"suggestible":true,"sources":["src/features/notifications/NotificationsSettings.tsx","src/features/notifications/capabilities.ts","src/features/notifications/NotificationsSettings.test.tsx"],"answer":"Open Settings and find Notifications to review the available reminder preferences and device permission status. Available controls depend on browser and device support."},{"id":"missing-checkin-reminder","category":"notifications","question":"How does the missing check-in reminder work?","aliases":["Why does Today show a missing check-in reminder?","When are overdue check-ins highlighted?"],"keywords":["Today","missing check-in","overdue","reminder","schedule"],"suggestible":true,"sources":["src/features/today/TodayPage.tsx","src/features/notifications/reminderRules.ts","src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/reminderRules.test.ts"],"answer":"The app can highlight unresolved check-in opportunities in its foreground experience, and History reviews missing opportunities from the previous seven completed days. These reminders depend on tracker schedules and active dates; they do not mean a saved check-in was deleted."},{"id":"reminder-previous-day-only","category":"notifications","question":"How far back does the overdue reminder look?","aliases":["Does the reminder scan all old missed days?","Will it notify me about every historical gap?"],"keywords":["overdue reminder","yesterday","historical","missed check-ins"],"suggestible":true,"sources":["src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/reminderRules.ts"],"answer":"The overdue reminder checks unresolved required opportunities from yesterday. It does not scan every historical date. Future opportunities are Upcoming and do not trigger overdue reminders. History separately offers a review of missing opportunities from the previous seven completed days."},{"id":"reminder-dismissal","category":"notifications","question":"Does dismissing a missing check-in reminder complete the date?","aliases":["If I close a reminder, is the check-in marked done?","Does dismissing a notification resolve the missed day?"],"keywords":["dismiss reminder","mark complete","check-in","notification"],"suggestible":true,"sources":["src/db/localRepository.ts","src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/reminderRules.ts"],"answer":"No. Dismissing a notification changes the reminder’s read state; it does not create a check-in or mark the date complete. The date’s progress status changes only when you save or edit a check-in."},{"id":"reminder-foreground-check","category":"notifications","question":"Why do reminders run only while ProgressTracker is open?","aliases":["Does the app check for reminders in the background?","Why did no reminder arrive after I closed the app?"],"keywords":["foreground","background","scheduler","reminders","app open"],"suggestible":true,"sources":["src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/NotificationsSettings.tsx"],"answer":"The reminder monitor evaluates reminders while the signed-in app is active. The Settings page reports that closed-app delivery still requires server-side sending and scheduling setup, so enabling device permission alone does not provide background reminders."},{"id":"reminder-timezone-quiet","category":"notifications","question":"Which time zone and quiet hours affect reminders?","aliases":["Are notification times based on my workspace time zone?","Why was a reminder delayed during quiet hours?"],"keywords":["reminder time","workspace time zone","quiet hours","schedule"],"suggestible":true,"sources":["src/features/notifications/NotificationsSettings.tsx","src/features/notifications/reminderRules.ts","src/features/notifications/ForegroundReminderMonitor.tsx"],"answer":"Reminder times use the workspace time zone. Quiet hours suppress daily and motivation reminders; overdue reminders also pause during quiet hours unless their exception is enabled."},{"id":"reminder-repeats-unresolved","category":"notifications","question":"Why can I get another reminder for the same unresolved date?","aliases":["Why did dismissing a reminder not stop later reminders?","Can reminders repeat while I have not checked in?"],"keywords":["reminder","repeats","unresolved","daily schedule","dismissal"],"suggestible":true,"sources":["src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/reminderRules.ts","src/db/localRepository.ts"],"answer":"Daily reminders are evaluated at their configured times while the app is active. Dismissing one marks that notification as read; it does not resolve the opportunity, so a later scheduled reminder can still appear while the check-in remains unresolved."},{"id":"local-settings","category":"settings-privacy","question":"Do my appearance and time zone settings sync?","aliases":["Will dark mode carry to another device?","Does changing my time zone sync to my account?"],"keywords":["appearance","time zone","settings","local","sync"],"suggestible":true,"sources":["src/features/settings/appearance.ts","src/features/settings/WorkspaceTimeZone.tsx","src/services/supabase/syncEngine.ts","src/features/settings/appearance.test.ts","src/features/settings/WorkspaceAppearance.test.tsx"],"answer":"Appearance and workspace time-zone preferences are stored locally and are not part of the account records synchronized between devices. Set them separately on each device where you use the app."},{"id":"timezone-dates","category":"settings-privacy","question":"Do check-in dates change when I change my time zone?","aliases":["Will my old entries move to a different day?","How does the workspace time zone affect tracking?"],"keywords":["time zone","calendar date","historical","check-in","local date"],"suggestible":true,"sources":["src/features/settings/WorkspaceTimeZone.tsx","src/db/calendarDate.ts","src/db/calendarDate.test.ts"],"answer":"Check-ins are stored by calendar date, so changing the workspace time zone does not shift already saved entries to another day. The selected time zone affects how dates and new daily boundaries are interpreted."},{"id":"completion-rate","category":"statistics","question":"How is completion rate calculated?","aliases":["How do you calculate my completion percentage?","Why is my completion rate lower than expected?","What is the denominator for completion rate?"],"keywords":["percentage","consistency","scheduled opportunities","qualifying entries","denominator","analytics"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/planning.ts","src/domain/trackers/progression.ts","src/domain/trackers/analytics.test.ts"],"answer":"For an active tracker with scheduled opportunities, the consistency percentage is the number of qualifying opportunities divided by the number of counted opportunities, rounded to a whole percent. Standard Mode counts scheduled dates except holidays; Strict Mode counts every active date, including otherwise unscheduled dates and holidays. The current as-of date is left out when it has no entry yet. If there are no counted opportunities, the percentage is unavailable."},{"id":"qualifying-checkin","category":"statistics","question":"What makes a check-in count as successful?","aliases":["What counts as a completed day?","Why did my check-in not count toward progress?"],"keywords":["success rule","threshold","qualifying","recorded","outcome","measure"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/trackers/types.ts"],"answer":"A recorded check-in qualifies when its outcome and values meet the tracker’s configured success rules. A tracker can have multiple measures and rules, so recording something does not always mean the day qualifies. A skipped check-in is not a qualifying recorded result."},{"id":"points-and-rewards","category":"statistics","question":"How do achievement points and streak rewards work?","aliases":["Do I lose reward points if my streak resets?","What earns points in Achievements?"],"keywords":["achievements","points","reward","qualified check-in","milestone","longest streak"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/features/dashboard/AchievementsPage.tsx"],"answer":"Each qualifying check-in earns points, and reaching a new longest-streak milestone earns additional points. A missed day can end the current streak, but it does not subtract points already earned. Achievements are calculated from the tracker’s saved history, so editing or clearing history can recalculate the totals."},{"id":"completion-missed-dates","category":"statistics","question":"Do missed dates affect completion rate?","aliases":["Does a missed day lower my consistency percentage?","Why did my completion rate decrease after an unchecked day?"],"keywords":["completion rate","missed opportunity","denominator","consistency"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/analytics.test.ts"],"answer":"Counted opportunities contribute to the denominator, while qualifying entries contribute to the numerator. A missed counted opportunity therefore lowers the percentage. Standard Mode excludes holidays and unscheduled days; Strict Mode counts every active date."},{"id":"completion-holidays-rest-days","category":"statistics","question":"Do holidays and rest days affect completion rate?","aliases":["Are holidays included in consistency statistics?","Do unscheduled dates count in the percentage?"],"keywords":["completion rate","holidays","rest days","Standard Mode","Strict Mode"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/analytics.test.ts","src/domain/trackers/planning.ts"],"answer":"In Standard Mode, holidays and unscheduled rest days are excluded from counted opportunities. Strict Mode counts every active date, including holidays and dates outside the regular schedule. A saved qualifying check-in on a holiday can count in either mode."},{"id":"completion-no-opportunities","category":"statistics","question":"Why is a tracker’s completion rate unavailable?","aliases":["Why is there no percentage for this tracker?","What if my tracker has no counted dates yet?"],"keywords":["completion rate","no opportunities","active period","schedule"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/planning.ts"],"answer":"The percentage is unavailable when there are no counted opportunities in the selected period. This can happen before a tracker’s active period or when its schedule and mode produce no opportunities in that range."},{"id":"analytics-metric-units","category":"statistics","question":"Does Analytics combine different measure units into one total?","aliases":["Are pages and minutes added together in Analytics?","How does Insights summarize multiple kinds of values?"],"keywords":["Analytics","Insights","measures","units","observations"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/features/analytics/AnalyticsPage.tsx"],"answer":"No. Analytics summarizes each measure separately, so values with different units are not added together. Comparable counts such as completed opportunities can be combined, while measure values stay with their own tracker and unit."},{"id":"completion-holiday-entry","category":"statistics","question":"Does a check-in on a holiday count toward completion rate?","aliases":["If I log on a holiday, does my percentage go up?","Does holiday progress count in consistency statistics?"],"keywords":["completion rate","holiday","qualifying check-in","Strict Mode","Standard Mode"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/analytics.test.ts"],"answer":"It depends on the tracker’s mode. Standard Mode excludes holidays from counted opportunities, so a holiday entry does not affect that rate. Strict Mode counts every active date, including holidays, and a qualifying saved entry contributes to the rate."},{"id":"standard-vs-strict","category":"streaks","question":"What is the difference between Standard Mode and Strict Mode?","aliases":["Does Strict Mode count rest days?","Which days become opportunities in Strict Mode?"],"keywords":["Standard Mode","Strict Mode","schedule","daily","opportunity","holidays"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/analytics.ts","src/features/trackers/TrackerConfigurationEditor.tsx"],"answer":"Standard Mode counts the tracker’s scheduled dates as opportunities and pauses over unscheduled days and holidays. Strict Mode counts every date in the active period, including unscheduled dates and holidays. A saved qualifying check-in on a holiday can still count in either mode."},{"id":"streak-statistics","category":"streaks","question":"How do streak statistics work?","aliases":["How are streaks calculated?","What counts toward my current streak?","Why did my streak reset?"],"keywords":["current streak","longest streak","qualifying check-in","schedule","strict mode","rest day","holiday"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/trackers/progression.test.ts"],"answer":"Your current streak is the run of recent tracking opportunities you have met. Your longest streak is the best qualifying run in the tracker’s history. A missed required opportunity can end the current run, while the longest record remains. Which dates count depends on the tracker’s schedule, Strict Mode, and holidays."},{"id":"rest-days-streaks","category":"streaks","question":"How do rest days affect streaks?","aliases":["Do unscheduled days break a streak?","Does my schedule pause my streak?"],"keywords":["schedule","unscheduled","opportunity","strict mode","rest day"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts"],"answer":"In Standard Mode, only scheduled check-in dates are opportunities, so unscheduled rest days do not break a streak. Strict Mode treats every active date as an opportunity, including dates outside the regular schedule. Tracker start and deadline dates still bound the active period."},{"id":"streak-longest","category":"streaks","question":"What is the difference between my current streak and longest streak?","aliases":["Does losing my streak erase my record?","Why is my longest streak higher than my current streak?"],"keywords":["current streak","longest streak","record","history"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/progression.test.ts"],"answer":"Your current streak describes your ongoing qualifying run. Your longest streak is the best qualifying run found in the tracker’s history, so a current streak ending does not erase that record."},{"id":"streak-skipped","category":"streaks","question":"Does marking a check-in as skipped count toward a streak?","aliases":["Is an intentionally missed entry a completed day?","Does “Marked missed intentionally” qualify for a streak?"],"keywords":["skipped","marked missed","streak","qualifying entry"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/progression.test.ts","src/features/history/HistoryPage.tsx"],"answer":"No. A Skipped entry is a saved intentional outcome, not a derived Missed date or a recorded No progress check-in. It does not qualify for a streak on a required opportunity. Standard Mode rest days and holidays are excluded from the streak; Strict Mode requires qualifying activity on every in-period date."},{"id":"streak-zero-quantity","category":"streaks","question":"Does recording zero keep a streak alive?","aliases":["Can a zero quantity value qualify for a streak?","Why did my zero entry not count toward my streak?"],"keywords":["zero","quantity","streak qualification","success rule"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/progression.test.ts"],"answer":"A numeric zero does not qualify through the default streak rule, which requires a finite value greater than zero. A tracker with an explicit streak qualification uses that configured rule instead, so check its settings when the result is unexpected."},{"id":"restore-deleted-tracker","category":"trackers","question":"Can I restore a deleted tracker?","aliases":["Where do deleted trackers go?","How do I recover a tracker from the Bin?"],"keywords":["Bin","restore","deleted tracker","archive","recover"],"suggestible":true,"sources":["src/features/trackers/TrackerBinPage.tsx","src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerBinPage.test.tsx"],"answer":"Trackers deleted through the tracker flow appear in The Bin, where you can choose Restore. Archiving or pausing a tracker is different: it stays in your tracker library and keeps its history."},{"id":"bin-retention","category":"trackers","question":"What happens to a tracker after I delete it?","aliases":["Is a deleted tracker erased immediately?","How long can I restore something from The Bin?"],"keywords":["delete","Bin","soft delete","restore","retention","permanent deletion"],"suggestible":false,"sources":["src/features/trackers/TrackerBinPage.tsx","src/db/localRepository.ts","supabase/migrations/20261013000200_schedule_tracker_bin_cleanup.sql"],"answer":"Deleting a tracker moves it to The Bin, where it can be restored for 30 days with its saved progress and plan, or permanently deleted after server confirmation. Automatic removal depends on whether the deployment has enabled the scheduled database cleanup; the Bin explains the policy active in that deployment."},{"id":"edit-tracker-history","category":"trackers","question":"Do tracker edits change historical statistics?","aliases":["What happens to old stats when I edit a tracker?","Can changing a measure change old entries?"],"keywords":["edit","historical","measure type","schedule","statistics"],"suggestible":true,"sources":["src/domain/trackers/invariants.ts","src/features/trackers/TrackerConfigurationEditor.tsx","src/domain/trackers/analytics.ts"],"answer":"Some edits can change which dates count in schedule-based statistics, because calculations use the tracker’s current schedule and active period. A saved measure’s type and historical interpretation are protected. Retiring a measure removes it from future check-ins while retaining its definition for old entries."},{"id":"archive-tracker","category":"trackers","question":"What happens when I archive a tracker?","aliases":["Does archiving delete my tracker history?","Can I restore a paused tracker?"],"keywords":["archive","pause","active","history","delete"],"suggestible":true,"sources":["src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerBinPage.tsx"],"answer":"Archiving or pausing a tracker stops it being active for future opportunities but keeps its recorded history. Deleting a tracker is a separate action that moves it through the app’s Bin and restore flow."},{"id":"tracker-schedules","category":"trackers","question":"How do tracker schedules work?","aliases":["Which days count as scheduled?","How do I choose tracking days?"],"keywords":["schedule","weekly","daily","weekdays","opportunity"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/features/trackers/TrackerSetupPage.tsx"],"answer":"The schedule defines the regular days when a tracker has a check-in opportunity. You choose it while creating or editing a tracker. Standard Mode uses those scheduled dates for streak and consistency opportunities; Strict Mode treats every active date as an opportunity."},{"id":"start-date-deadline","category":"trackers","question":"How do a tracker’s start date and deadline affect it?","aliases":["When does a tracker begin counting?","Does a deadline stop future check-ins?"],"keywords":["start date","deadline","active period","schedule","tracker"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/activePeriod.test.ts","src/domain/trackers/planning.test.ts","src/features/trackers/TrackerSetupPage.tsx"],"answer":"The tracker’s active period is bounded by its start date and, when set, its deadline. Dates outside that period are not active tracking opportunities. A deadline therefore stops schedule-based calculations from counting later dates."},{"id":"retire-measure","category":"trackers","question":"What happens when I retire a measure?","aliases":["Can I remove a measure but keep its history?","Why is an old measure still shown in History?"],"keywords":["retire","measure","old entries","history","future check-ins"],"suggestible":true,"sources":["src/features/trackers/TrackerConfigurationEditor.tsx","src/domain/trackers/types.ts","src/domain/trackers/schema.test.ts","src/features/history/HistoryPage.tsx"],"answer":"Retiring a measure removes it from future check-ins while keeping its definition available to interpret older entries. That is why an old measure may still appear when you review historical data."},{"id":"tracker-editing","category":"trackers","question":"How do I edit a tracker?","aliases":["Where can I change a tracker’s schedule?","Can I add another measure to a tracker?"],"keywords":["edit","tracker","schedule","measures","configuration"],"suggestible":true,"sources":["src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerConfigurationEditor.tsx","src/features/trackers/TrackerSetupPage.tsx","src/features/trackers/TrackerSetupPage.test.tsx"],"answer":"Open Trackers, choose the tracker’s edit action, update its supported settings, then save. You can change configuration such as its schedule and add measures, while saved measure types and their historical meaning are protected."},{"id":"tracker-created-active-date","category":"trackers","question":"Does a tracker count dates before I created it?","aliases":["Does its start date include days before the tracker existed?","Why does a tracker created today start counting today?"],"keywords":["tracker creation date","start date","active period","workspace time zone"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/activePeriod.test.ts"],"answer":"No. The effective active period starts on the later of the configured start date and the tracker’s creation date in the workspace time zone. Earlier dates are outside the tracker’s active period."},{"id":"archived-checkin-history","category":"trackers","question":"Can I edit check-ins after archiving a tracker?","aliases":["Is archived tracker history read-only?","Does archiving keep old entries but stop edits?"],"keywords":["archived tracker","check-in","history","read-only","archive"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/features/trackers/TrackerLibraryPage.tsx"],"answer":"Archiving keeps the tracker’s saved history, but its check-ins are read-only while the tracker is archived. Restore it to active status if you need to edit its check-ins again."}] as const
